def seed_specialties(apps, schema_editor):
    Specialty = apps.get_model('video_registry', 'Specialty')
    for name, slug, description, display_order in SPECIALTIES:
        Specialty.objects.get_or_create(slug=slug, defaults={
            'name': name, 'description': description, 'display_order': display_order, 'is_active': True,
        })


def unseed_specialties(apps, schema_editor):
    Specialty = apps.get_model('video_registry', 'Specialty')
    for _, slug, _, _ in SPECIALTIES:
        row = Specialty.objects.filter(slug=slug).first()
        if row and not row.providers.exists() and not row.offerings.exists() and not row.subscription_plans.exists():
            row.delete()


